OUT_DIR = "/home/hatch/workspace/divination/benchmark/phase3/runs/round88/predictions"
DATA = {}

def add(case_id, prediction_text, basis, confidence, changed_main=False, reserve_used=False, disputed=False, reason=""):
    DATA[case_id] = {
        "case_id": case_id,
        "prediction_text": prediction_text,
        "basis": basis,
        "confidence": confidence,
        "trigger": {"changed_main": changed_main, "reserve_used": reserve_used, "disputed": disputed, "reason": reason},
    }

