# ================= 落盘 + 逐件自验 =================
IDS = ["LY-614","LY-615","LY-616","LY-617","LY-618","LY-619","LY-620","LY-621","LY-622","LY-623",
       "LY-624","LY-625","LY-626","LY-627","LY-628","LY-629",
       "MH-001","MH-002","MH-003","MH-006","MH-007","MH-008","MH-009","MH-010",
       "MP-001","MP-002","MP-003","MP-004","MP-005","MP-006","MP-007","MP-008","MP-009","MP-010",
       "MP-011","MP-012","MP-013","MP-014","MP-015","MP-016"]
assert len(IDS) == 40 and set(IDS) == set(DATA.keys()), (len(IDS), set(IDS) ^ set(DATA.keys()))
os.makedirs(OUT_DIR, exist_ok=True)
total_bytes = 0
for cid in IDS:
    obj = DATA[cid]
    path = os.path.join(OUT_DIR, cid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)
    total_bytes += os.path.getsize(path)
print("written:", len(IDS), "total_bytes:", total_bytes)

# 逐件精确打开自验（按 id 清单逐件，不列目录）
ok = 0
trig = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
for cid in IDS:
    path = os.path.join(OUT_DIR, cid + ".json")
    with open(path, encoding="utf-8") as f:
        o = json.load(f)
    assert set(o.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}, (cid, o.keys())
    assert o["case_id"] == cid
    assert isinstance(o["confidence"], (int, float)) and 0.0 <= o["confidence"] <= 1.0, cid
    t = o["trigger"]
    assert set(t.keys()) == {"changed_main","reserve_used","disputed","reason"}, cid
    for k in ("changed_main","reserve_used","disputed"):
        assert isinstance(t[k], bool), (cid, k)
        if cid.startswith("LY-") and t[k]:
            trig[k] += 1
    assert isinstance(t["reason"], str)
    if not cid.startswith("LY-"):
        assert t == {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}, cid
    ok += 1
print("verified:", ok)
print("liuyao_trigger_counts:", trig)
